            hvp2_rr_a(3, 2, 3) = hvp2_rr_a(3, 2, 3) + t_hvp2_rr_a_122
            hvp2_rr_a(3, 3, 1) = hvp2_rr_a(3, 3, 1) + (x100)
            hvp2_rr_a(3, 3, 2) = hvp2_rr_a(3, 3, 2) + (x102)
            hvp2_rr_a(3, 3, 3) = hvp2_rr_a(3, 3, 3) + (vr_a*x91)
            rh0_a = &
               rh0_a + (v_a(1)*x13 + v_a(1)*x16 + v_a(2)*x18 + v_a(2)*x19 + v_a(3)*x21 + &
               v_a(3)*x22 + vr_a*(x103*x5 + x104*x8))
            rh1_r_a(1) = &
               rh1_r_a(1) + (-v_a(1)*x33 - v_a(2)*x38 - v_a(3)*x41 + vr_a*(d_a(1)*x105 + &
               d_a(1)*x106 + d_a(1)*x108))
            rh1_r_a(2) = &
               rh1_r_a(2) + (-v_a(1)*x38 - v_a(2)*x43 - v_a(3)*x46 + vr_a*(d_a(2)*x105 + &
               d_a(2)*x106 + d_a(2)*x108))
            rh1_r_a(3) = &
               rh1_r_a(3) + (-v_a(1)*x41 - v_a(2)*x46 - v_a(3)*x48 + vr_a*(d_a(3)*x105 + &
               d_a(3)*x106 + d_a(3)*x108))
            rh2_rr_a(1, 1) = &
               rh2_rr_a(1, 1) + (-v_a(1)*x58 - v_a(2)*x64 - v_a(3)*x68 + vr_a*(x109*x59 - x110*x59 &
               + x111*x2 + x112*x26 + x113))
            t_rh2_rr_a_01 = &
               -v_a(1)*x64 - v_a(2)*x75 - v_a(3)*x78 + vr_a*(d_a(2)*x115 + x111*x117 - x116*x117 + &
               x117*x118)
            rh2_rr_a(1, 2) = rh2_rr_a(1, 2) + t_rh2_rr_a_01
            rh2_rr_a(2, 1) = rh2_rr_a(2, 1) + t_rh2_rr_a_01
            t_rh2_rr_a_02 = &
               -v_a(1)*x68 - v_a(2)*x78 - v_a(3)*x80 + vr_a*(d_a(3)*x115 + x111*x119 - x116*x119 + &
               x118*x119)
            rh2_rr_a(1, 3) = rh2_rr_a(1, 3) + t_rh2_rr_a_02
            rh2_rr_a(3, 1) = rh2_rr_a(3, 1) + t_rh2_rr_a_02
            rh2_rr_a(2, 2) = &
               rh2_rr_a(2, 2) + (-v_a(1)*x75 - v_a(2)*x83 - v_a(3)*x86 + vr_a*(x111*x3 + x113 + &
               x114*x3 - x116*x3 + x118*x3))
            t_rh2_rr_a_12 = &
               -v_a(1)*x78 - v_a(2)*x86 - v_a(3)*x89 + vr_a*(x111*x76 + x114*x76 - x116*x76 + &
               x118*x76)
            rh2_rr_a(2, 3) = rh2_rr_a(2, 3) + t_rh2_rr_a_12
            rh2_rr_a(3, 2) = rh2_rr_a(3, 2) + t_rh2_rr_a_12
            rh2_rr_a(3, 3) = &
               rh2_rr_a(3, 3) + (-v_a(1)*x80 - v_a(2)*x89 - v_a(3)*x92 + vr_a*(x111*x4 + x113 + &
               x114*x4 - x116*x4 + x118*x4))
         end block
      end select

   end subroutine cfc_atomic_radius_hvp_eval

   pure module subroutine cfc_pair_radius_hvp_eval(d_a, d_b, R_a, R_b, a2, c_par, fade_start, &
                                            fade_width, v_a, v_b, vr_a, vr_b, max_deriv, tg0, &
                                            tg1_r, tg2_rr, tg3_rrr, hvp0_a, hvp0_b, hvp1_r_a, &
                                            hvp1_r_b, hvp2_rr_a, hvp2_rr_b, rh0_a, rh0_b, &
                                            rh1_r_a, rh1_r_b, rh2_rr_a, rh2_rr_b)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Nuclear displacement direction of atom a
      real(wp), intent(in) :: v_a(3)
      !> Nuclear displacement direction of atom b
      real(wp), intent(in) :: v_b(3)
      !> Radius direction of atom a
      real(wp), intent(in) :: vr_a
      !> Radius direction of atom b
      real(wp), intent(in) :: vr_b
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the position half
      !> accumulated by cfc_pair_hvp_eval
      real(wp), intent(inout) :: tg0
      !> sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the position half
      !> accumulated by cfc_pair_hvp_eval
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the position half
      !> accumulated by cfc_pair_hvp_eval
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the position half
      !> accumulated by cfc_pair_hvp_eval
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-0 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp0_a(3)
      !> sum_B vr_B d2/(dr_b dR_B) of the order-0 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom b
      real(wp), intent(inout) :: hvp0_b(3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-1 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp1_r_a(3, 3)
      !> sum_B vr_B d2/(dr_b dR_B) of the order-1 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom b
      real(wp), intent(inout) :: hvp1_r_b(3, 3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-2 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp2_rr_a(3, 3, 3)
      !> sum_B vr_B d2/(dr_b dR_B) of the order-2 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom b
      real(wp), intent(inout) :: hvp2_rr_b(3, 3, 3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-0 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh0_a
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_b of the order-0 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh0_b
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-1 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh1_r_a(3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_b of the order-1 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh1_r_b(3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-2 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh2_rr_a(3, 3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_b of the order-2 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh2_rr_b(3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a, sg_b

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      sg_b = (sqrt(d_b(1)*d_b(1) + d_b(2)*d_b(2) + d_b(3)*d_b(3)) - R_b)*(1.0_wp/R_b)
      if (sg_a > fade_start .or. sg_b > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         call cfc_pair_radius_hvp_eval_faded(d_a, d_b, R_a, R_b, a2, c_par, fade_start, &
                                             fade_width, v_a, v_b, vr_a, vr_b, max_deriv, tg0, &
                                             tg1_r, tg2_rr, tg3_rrr, hvp0_a, hvp0_b, hvp1_r_a, &
                                             hvp1_r_b, hvp2_rr_a, hvp2_rr_b, rh0_a, rh0_b, &
                                             rh1_r_a, rh1_r_b, rh2_rr_a, rh2_rr_b, sg_a, sg_b)
         return
      end if

      ! Plateau: plain term, w = 1
      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84

            x0 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
            x1 = sqrt(x0)
            x2 = 1.0_wp/(R_a*R_a)
            x3 = 1.0_wp/R_a
            x4 = 1.0_wp/R_b
            x5 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
            x6 = x4*x5
            x7 = -x3*x6 + 1.0_wp
            x8 = (x7*x7*x7*x7)
            x9 = (d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))
            x10 = sqrt(x9)
            x11 = exp(a2*(x1*x3 + x10*x4 - 2.0_wp))
            x12 = c_par*x11
            x13 = x12*x8
            x14 = a2*x13
            x15 = x14*x2
            x16 = (x7*x7*x7)
            x17 = 1.0_wp/(R_b*R_b)
            x18 = x14*x17
            x19 = x12*x16
            x20 = 4.0_wp*x19
            x21 = x20*x3
            x22 = x17*x21
            x23 = 1.0_wp/(R_b*R_b*R_b)
            x24 = (x7*x7)
            x25 = a2*d_b(1)
            x26 = x10*x23
            x27 = x21*x26
            x28 = 1.0_wp/x1
            x29 = x2*x20
            x30 = x17*x5
            x31 = x29*x30
            x32 = a2*x31
            x33 = (a2*a2)
            x34 = &
               -c_par*d_a(1)*x10*x11*x17*x28*x3*x33*x8 - 12.0_wp*c_par*d_b(1)*x11*x2*x23*x24*x5 + &
               d_a(1)*x28*x32 + d_b(1)*x22 + x25*x27
            x35 = x13*x33
            x36 = 1.0_wp/(R_a*R_a*R_a)
            x37 = d_a(1)*x36
            x38 = x29*x4
            x39 = x15*x28
            x40 = 12.0_wp*x12*x24
            x41 = x30*x36
            x42 = x1*x36
            x43 = x20*x4
            x44 = x42*x43
            x45 = a2*x20
            x46 = x28*x45
            x47 = d_a(1)*x39 - d_b(1)*x38 + d_b(1)*x40*x41 - x25*x44 + x35*x37 - x37*x46*x6
            x48 = a2*d_b(2)
            x49 = x28*x32
            x50 = &
               -c_par*d_a(2)*x10*x11*x17*x28*x3*x33*x8 - 12.0_wp*c_par*d_b(2)*x11*x2*x23*x24*x5 + &
               d_a(2)*x49 + d_b(2)*x22 + x27*x48
            x51 = x35*x36
            x52 = x36*x6
            x53 = x46*x52
            x54 = d_a(2)*x39 + d_a(2)*x51 - d_a(2)*x53 - d_b(2)*x38 + d_b(2)*x40*x41 - x44*x48
            x55 = a2*d_b(3)
            x56 = &
               -c_par*d_a(3)*x10*x11*x17*x28*x3*x33*x8 - 12.0_wp*c_par*d_b(3)*x11*x2*x23*x24*x5 + &
               d_a(3)*x49 + d_b(3)*x22 + x27*x55
            x57 = d_a(3)*x39 + d_a(3)*x51 - d_a(3)*x53 - d_b(3)*x38 + d_b(3)*x40*x41 - x44*x55
            x58 = a2*x1
            x59 = 1.0_wp/x10
            x60 = x25*x59
            x61 = &
               -12.0_wp*c_par*d_a(1)*x11*x17*x24*x36*x5 - c_par*d_b(1)*x1*x11*x2*x33*x4*x59*x8 + &
               d_a(1)*x38 + x31*x60 + x37*x43*x58
            x62 = x23*x35
            x63 = x18*x59
            x64 = x23*x5
            x65 = x2*x40*x64
            x66 = a2*x27
            x67 = x21*x64
            x68 = -d_a(1)*x22 + d_a(1)*x65 - d_a(1)*x66 + d_b(1)*x62 + d_b(1)*x63 - x60*x67
            x69 = a2*x44
            x70 = x48*x59
            x71 = &
               -12.0_wp*c_par*d_a(2)*x11*x17*x24*x36*x5 - c_par*d_b(2)*x1*x11*x2*x33*x4*x59*x8 + &
               d_a(2)*x38 + d_a(2)*x69 + x31*x70
            x72 = -d_a(2)*x22 + d_a(2)*x65 - d_a(2)*x66 + d_b(2)*x62 + d_b(2)*x63 - x67*x70
            x73 = x55*x59
            x74 = &
               -12.0_wp*c_par*d_a(3)*x11*x17*x24*x36*x5 - c_par*d_b(3)*x1*x11*x2*x33*x4*x59*x8 + &
               d_a(3)*x38 + d_a(3)*x69 + x31*x73
            x75 = -d_a(3)*x22 + d_a(3)*x65 - d_a(3)*x66 + d_b(3)*x62 + d_b(3)*x63 - x67*x73
            x76 = 1.0_wp/(R_a*R_a*R_a*R_a)
            x77 = 8.0_wp*x19
            x78 = 2.0_wp*x14
            x79 = (x5*x5)
            x80 = x40*x79
            x81 = a2*x10
            x82 = &
               c_par*x1*x10*x11*x17*x2*x33*x8 + 12.0_wp*c_par*x11*x23*x24*x36*x79 - x29*x64*x81 - &
               x30*x42*x45 - x31
            x83 = 1.0_wp/(R_b*R_b*R_b*R_b)
            x84 = x3*x77
            tg0 = &
               tg0 + (vr_a*(4.0_wp*c_par*x11*x16*x2*x4*x5 - x1*x15) + &
               vr_b*(4.0_wp*c_par*x11*x16*x17*x3*x5 - x10*x18))
            hvp0_a(1) = hvp0_a(1) + (vr_a*x47 - vr_b*x34)
            hvp0_a(2) = hvp0_a(2) + (vr_a*x54 - vr_b*x50)
            hvp0_a(3) = hvp0_a(3) + (vr_a*x57 - vr_b*x56)
            hvp0_b(1) = hvp0_b(1) + (-vr_a*x61 + vr_b*x68)
            hvp0_b(2) = hvp0_b(2) + (-vr_a*x71 + vr_b*x72)
            hvp0_b(3) = hvp0_b(3) + (-vr_a*x74 + vr_b*x75)
            rh0_a = &
               rh0_a + (v_a(1)*x47 + v_a(2)*x54 + v_a(3)*x57 - v_b(1)*x61 - v_b(2)*x71 - &
               v_b(3)*x74 + vr_a*(x0*x35*x76 + x17*x76*x80 + x42*x78 - x52*x77 - x58*x6*x76*x77) + &
               vr_b*x82)
            rh0_b = &
               rh0_b + (-v_a(1)*x34 - v_a(2)*x50 - v_a(3)*x56 + v_b(1)*x68 + v_b(2)*x72 + &
               v_b(3)*x75 + vr_a*x82 + vr_b*(x2*x80*x83 + x26*x78 + x35*x83*x9 - x5*x81*x83*x84 - &
               x64*x84))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93, x94, x95, x96, x97, x98, x99, x100, x101, x102, x103, x104, x105
            real(wp) :: x106, x107, x108, x109, x110, x111, x112, x113, x114, x115, x116, x117, x118
            real(wp) :: x119, x120, x121, x122, x123, x124, x125, x126, x127, x128, x129, x130, x131
            real(wp) :: x132, x133, x134, x135, x136, x137, x138, x139, x140, x141, x142, x143, x144
            real(wp) :: x145, x146, x147, x148, x149, x150, x151, x152, x153, x154, x155, x156, x157
            real(wp) :: x158, x159, x160, x161, x162, x163, x164, x165, x166, x167, x168, x169, x170
            real(wp) :: x171, x172, x173, x174, x175, x176, x177, x178, x179, x180, x181, x182, x183
            real(wp) :: x184, x185, x186, x187, x188, x189, x190, x191, x192, x193, x194, x195, x196
            real(wp) :: x197, x198, x199, x200, x201, x202, x203, x204, x205, x206, x207, x208, x209
            real(wp) :: x210, x211, x212, x213, x214, x215, x216, x217, x218, x219, x220, x221, x222
            real(wp) :: x223, x224, x225, x226, x227, x228, x229, x230, x231, x232, x233, x234, x235
            real(wp) :: x236, x237, x238, x239, x240, x241, x242, x243, x244, x245, x246, x247, x248
            real(wp) :: x249, x250, x251, x252, x253, x254, x255, x256, x257, x258, x259, x260, x261
            real(wp) :: x262, x263, x264, x265, x266, x267, x268, x269, x270, x271, x272, x273, x274
            real(wp) :: x275, x276, x277, x278, x279, x280, x281, x282, x283, x284, x285, x286, x287
            real(wp) :: x288, x289, x290, x291, x292, x293, x294, x295, x296, x297, x298, x299, x300
            real(wp) :: x301, x302, x303, x304, x305, x306, x307, x308, x309, x310, x311, x312, x313
            real(wp) :: x314, x315, x316, x317, x318, x319, x320, x321, x322, x323, x324, x325, x326
            real(wp) :: x327, x328, x329, x330, x331, x332, x333, x334, x335, x336, x337, x338, x339
            real(wp) :: x340, x341, x342, x343, x344, x345, x346, x347, x348, x349, x350, x351, x352
            real(wp) :: x353, x354, x355, x356, x357, x358, x359, x360, x361, x362, x363, x364, x365
            real(wp) :: x366, x367, x368, x369, x370, x371, x372, x373, x374, x375, x376, x377, x378
            real(wp) :: x379, x380, x381, x382, x383, x384, x385, x386, x387, x388, x389, x390, x391
